def ser(vals, L, R):
    out = [str(vals[0])]
    q = [0]
    h = 0
    while h < len(q):
        u = q[h]
        h += 1
        for c in (L[u], R[u]):
            if c < 0:
                out.append('null')
            else:
                out.append(str(vals[c]))
                q.append(c)
    while out[-1] == 'null':
        out.pop()
    return ' '.join(out)

def rand_tree(n, rng, maxd, valf, deep=0.0):
    L = [-1] * n
    R = [-1] * n
    vals = [valf(rng) for _ in range(n)]
    dep = [1] * n
    slots = [(0, 0), (0, 1)] if maxd >= 2 else []
    for i in range(1, n):
        if rng.random() < deep:
            j = len(slots) - 1
            if len(slots) > 1 and rng.random() < 0.4:
                j -= 1
        else:
            j = rng.randrange(len(slots))
        slots[j], slots[-1] = slots[-1], slots[j]
        p, s = slots.pop()
        if s == 0:
            L[p] = i
        else:
            R[p] = i
        dep[i] = dep[p] + 1
        if dep[i] < maxd:
            slots.append((i, 0))
            slots.append((i, 1))
    return ser(vals, L, R)

def complete_tree(n, rng, valf):
    vals = [valf(rng) for _ in range(n)]
    L = [2 * i + 1 if 2 * i + 1 < n else -1 for i in range(n)]
    R = [2 * i + 2 if 2 * i + 2 < n else -1 for i in range(n)]
    return ser(vals, L, R)

